def process(loadMetropolitanHtml):
    import pandas as pd
    from bs4 import BeautifulSoup
    import re

    html = loadMetropolitanHtml['html'].iloc[0]
    soup = BeautifulSoup(html, 'html.parser')

    def norm_name(s: str) -> str:
        if s is None:
            return None
        s = str(s)
        s = re.sub(r'\[[^\]]*\]', '', s)  # citation brackets
        s = re.sub(r'\([^)]*\)', '', s)    # parentheticals
        s = s.lower()
        # remove common suffixes; keep city/state portion
        s = re.sub(r'\b(metropolitan|micropolitan)\s+statistical\s+area\b', '', s)
        s = re.sub(r'\bmetropolitan\s+area\b', '', s)
        s = re.sub(r'\bmicropolitan\s+area\b', '', s)
        s = re.sub(r'\bmsa\b', '', s)
        s = s.replace('–', '-').replace('—', '-')
        # keep commas and hyphens as separators; drop other punctuation
        s = re.sub(r"[^a-z0-9,\-\s]", ' ', s)
        s = re.sub(r'\s+', ' ', s).strip()
        return s

    def parse_int(x):
        if x is None:
            return None
        x = str(x)
        x = re.sub(r'\[[^\]]*\]', '', x)
        m = re.search(r'(\d[\d,]*)', x)
        if not m:
            return None
        return int(m.group(1).replace(',', ''))

    # Try to locate the "Metropolitan statistical areas" table (or closest)
    target_table = None
    for tbl in soup.select('table.wikitable'):
        header_text = ' '.join(th.get_text(' ', strip=True) for th in tbl.select('tr th')[:20]).lower()
        if ('msa' in header_text or 'metropolitan' in header_text) and ('2010' in header_text and '2020' in header_text):
            target_table = tbl
            break

    if target_table is None:
        # fallback: pick first wikitable that contains both 2010 and 2020 in any header row
        for tbl in soup.select('table.wikitable'):
            ths = [th.get_text(' ', strip=True).lower() for th in tbl.select('tr th')]
            if any('2010' in t for t in ths) and any('2020' in t for t in ths):
                target_table = tbl
                break

    if target_table is None:
        return pd.DataFrame(columns=['msa_name','msa_norm','pop2010','pop2020','pop2023_est'])

    # determine column indices from header row (the one that contains 2010 & 2020)
    header_rows = target_table.select('tr')[:5]
    header_cells = None
    for tr in header_rows:
        ths = tr.find_all('th')
        texts = [th.get_text(' ', strip=True) for th in ths]
        if any('2010' in t for t in texts) and any('2020' in t for t in texts):
            header_cells = texts
            break
    if header_cells is None:
        return pd.DataFrame(columns=['msa_name','msa_norm','pop2010','pop2020','pop2023_est'])

    def find_col(patterns):
        for i, t in enumerate(header_cells):
            tl = t.lower()
            if any(p in tl for p in patterns):
                return i
        return None

    col_name = 0  # usually first
    col2010 = find_col(['2010'])
    col2020 = find_col(['2020'])

    rows = []
    for tr in target_table.select('tr'):
        tds = tr.find_all('td')
        if not tds:
            continue
        # some tables include rank in first col; name might be second; handle by checking link/text
        # Build cell texts
        cell_texts = [td.get_text(' ', strip=True) for td in tds]
        # heuristically choose name cell as first cell containing a comma and a state abbreviation or ' - '
        name_idx = None
        for i, tx in enumerate(cell_texts[:3]):
            if ',' in tx and len(tx) >= 4:
                name_idx = i
                break
        if name_idx is None:
            name_idx = 0

        msa_name = cell_texts[name_idx]
        # Map header-based indices to td-based indices: if table has rank column, header_cells includes it too
        # Assume same count; if mismatch, try from end
        pop2010 = None
        pop2020 = None
        if col2010 is not None and col2010 < len(tds):
            pop2010 = parse_int(tds[col2010].get_text(' ', strip=True))
        if col2020 is not None and col2020 < len(tds):
            pop2020 = parse_int(tds[col2020].get_text(' ', strip=True))
        # if failed due to index mismatch, try last columns
        if pop2010 is None:
            for td in tds:
                if pop2010 is None and '2010' in td.get('data-sort-value',''):
                    pop2010 = parse_int(td.get_text(' ', strip=True))
        if pop2020 is None:
            # often 2020 is among the rightmost 3 cols; try scan for largest plausible
            candidates = [parse_int(td.get_text(' ', strip=True)) for td in tds]
            # keep only plausible pops
            cands = [c for c in candidates if c is not None and c > 50000]
            if len(cands) >= 2:
                # assume last is 2020, second last is 2010
                pop2020 = cands[-1]
                if pop2010 is None:
                    pop2010 = cands[-2]

        if pop2010 is None or pop2020 is None:
            continue

        pop2023 = pop2010 + (pop2020 - pop2010) * (13/10)
        rows.append({
            'msa_name': msa_name,
            'msa_norm': norm_name(msa_name),
            'pop2010': pop2010,
            'pop2020': pop2020,
            'pop2023_est': pop2023
        })

    df = pd.DataFrame(rows)
    df = df.dropna(subset=['msa_norm','pop2023_est'])
    return df

def process(matchMsaNames) -> pd.DataFrame:
    import pandas as pd

    df = matchMsaNames.copy()

    # Filter to metros with estimated 2023 population > 1,000,000
    df = df[pd.to_numeric(df['pop2023_est'], errors='coerce') > 1_000_000]

    avg_reports = pd.to_numeric(df['reports'], errors='coerce').mean()

    return pd.DataFrame([{
        'avg_reports_over_1m_pop_2023': float(avg_reports),
        'n_metros': int(df.shape[0])
    }])
